def rrf(rank_lists, k=60):
    scores = {}
    for ranking in rank_lists:
        for position, doc_id in enumerate(ranking, start=1):
            scores[doc_id] = scores.get(doc_id, 0) + 1 / (k + position)
    return sorted(scores, key=scores.get, reverse=True)

