def strict(pred, gold):
    return norm(pred) == norm(gold)

def soft(pred, gold, thr=0.9):
    from rapidfuzz.fuzz import token_set_ratio
    return token_set_ratio(norm(pred), norm(gold)) / 100 >= thr

